def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    start_i, start_j = -1, -1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start_i, start_j = i, j
                break
        if start_i != -1:
            break
    path = [1]
    i, j = start_i, start_j
    for _ in range(1, k):
        next_val = float('inf')
        next_i, next_j = -1, -1
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            ni, nj = i + dx, j + dy
            if 0 <= ni < n and 0 <= nj < n:
                if grid[ni][nj] < next_val:
                    next_val = grid[ni][nj]
                    next_i, next_j = ni, nj
        path.append(next_val)
        i, j = next_i, next_j
    return path

