def find_max(words):
    max_word = words[0]
    max_count = len(set(max_word))
    for word in words[1:]:
        unique_count = len(set(word))
        if unique_count > max_count:
            max_count = unique_count
            max_word = word
        elif unique_count == max_count:
            if word < max_word:
                max_word = word
    return max_word

